param([Parameter(Mandatory)][string]$OutputPath)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}

$assembly=[Reflection.Emit.AssemblyBuilder]::DefineDynamicAssembly([Reflection.AssemblyName]::new('DefaultEncodingFactories'),[Reflection.Emit.AssemblyBuilderAccess]::Run);$module=$assembly.DefineDynamicModule('probe');$builder=$module.DefineType('ArrayEncoding',[Reflection.TypeAttributes]'Public',[Text.Encoding]);$fields=@{};foreach($name in @('Multiplier','CountMode','WriteMode')){$fields[$name]=$builder.DefineField($name,[int],[Reflection.FieldAttributes]::Public)};$fields.Trace=$builder.DefineField('Trace',[Collections.Generic.List[int[]]],[Reflection.FieldAttributes]::Public)
$constructor=$builder.DefineConstructor([Reflection.MethodAttributes]::Public,[Reflection.CallingConventions]::Standard,[type[]]@());$il=$constructor.GetILGenerator();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Call,[Text.Encoding].GetConstructor([Reflection.BindingFlags]'Instance,NonPublic',$null,[type[]]@(),$null));$il.Emit([Reflection.Emit.OpCodes]::Ret)
foreach($abstract in [Text.Encoding].GetMethods()|Where-Object IsAbstract){[type[]]$parameters=@($abstract.GetParameters()|ForEach-Object ParameterType);$method=$builder.DefineMethod($abstract.Name,[Reflection.MethodAttributes]'Public,Virtual,HideBySig',$abstract.ReturnType,$parameters);$il=$method.GetILGenerator();$write=$abstract.Name -in @('GetBytes','GetChars');$count=$abstract.Name -in @('GetByteCount','GetCharCount');if($write -or $count){$kind=switch($abstract.Name){GetByteCount{0}GetBytes{1}GetCharCount{2}GetChars{3}};$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$fields.Trace);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_4);$il.Emit([Reflection.Emit.OpCodes]::Newarr,[int]);foreach($i in 0..3){$il.Emit([Reflection.Emit.OpCodes]::Dup);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4,$i);switch($i){0{$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4,$kind)}1{$il.Emit([Reflection.Emit.OpCodes]::Ldarg_2)}2{$il.Emit([Reflection.Emit.OpCodes]::Ldarg_3)}3{if($write){$il.Emit([Reflection.Emit.OpCodes]::Ldarg,[int16]5)}else{$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_M1)}}};$il.Emit([Reflection.Emit.OpCodes]::Stelem_I4)};$il.Emit([Reflection.Emit.OpCodes]::Callvirt,[Collections.Generic.List[int[]]].GetMethod('Add'))
 $mode=$il.DeclareLocal([int]);$normal=$il.DefineLabel();$nonNegative=$il.DefineLabel();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$fields[$(if($write){'WriteMode'}else{'CountMode'})]);$il.Emit([Reflection.Emit.OpCodes]::Stloc,$mode)
 if($write){$skip=$il.DefineLabel();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_3);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_0);$il.Emit([Reflection.Emit.OpCodes]::Ble,$skip);$il.Emit([Reflection.Emit.OpCodes]::Ldarg,[int16]4);$il.Emit([Reflection.Emit.OpCodes]::Ldarg,[int16]5);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4,42);$il.Emit($(if($abstract.Name -eq 'GetBytes'){[Reflection.Emit.OpCodes]::Stelem_I1}else{[Reflection.Emit.OpCodes]::Stelem_I2}));$il.MarkLabel($skip)}
 $il.Emit([Reflection.Emit.OpCodes]::Ldloc,$mode);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_1);$il.Emit([Reflection.Emit.OpCodes]::Bne_Un,$normal);$il.Emit([Reflection.Emit.OpCodes]::Ldstr,'array callback failure');$il.Emit([Reflection.Emit.OpCodes]::Newobj,[InvalidOperationException].GetConstructor([type[]]@([string])));$il.Emit([Reflection.Emit.OpCodes]::Throw);$il.MarkLabel($normal);$il.Emit([Reflection.Emit.OpCodes]::Ldloc,$mode);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_2);$il.Emit([Reflection.Emit.OpCodes]::Bne_Un,$nonNegative);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_M1);$il.Emit([Reflection.Emit.OpCodes]::Ret);$il.MarkLabel($nonNegative);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_3);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$fields.Multiplier);$il.Emit([Reflection.Emit.OpCodes]::Mul);$il.Emit([Reflection.Emit.OpCodes]::Ret)
 }else{$il.Emit([Reflection.Emit.OpCodes]::Ldarg_1);$il.Emit([Reflection.Emit.OpCodes]::Ret)};$builder.DefineMethodOverride($method,$abstract)}

foreach($kind in @(1,2)){[type[]]$parameters=if($kind -eq 1){@([int])}else{@([int],[Text.EncoderFallback],[Text.DecoderFallback])};$constructor=$builder.DefineConstructor([Reflection.MethodAttributes]::Public,[Reflection.CallingConventions]::Standard,$parameters);$il=$constructor.GetILGenerator();foreach($i in 0..$parameters.Length){$il.Emit([Reflection.Emit.OpCodes]::Ldarg,[int16]$i)};$il.Emit([Reflection.Emit.OpCodes]::Call,[Text.Encoding].GetConstructor([Reflection.BindingFlags]'Instance,NonPublic',$null,$parameters,$null));$il.Emit([Reflection.Emit.OpCodes]::Ret)}

$type=$builder.CreateType();$spoof=$module.DefineType('ReportedCodePageEncoding',[Reflection.TypeAttributes]'Public,Sealed',$type);$ctor=$spoof.DefineConstructor([Reflection.MethodAttributes]::Public,[Reflection.CallingConventions]::Standard,[type[]]@([int]));$il=$ctor.GetILGenerator();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_1);$il.Emit([Reflection.Emit.OpCodes]::Call,$type.GetConstructor([type[]]@([int])));$il.Emit([Reflection.Emit.OpCodes]::Ret);$getter=$spoof.DefineMethod('get_CodePage',[Reflection.MethodAttributes]'Public,Virtual,HideBySig,SpecialName',[int],[type[]]@());$il=$getter.GetILGenerator();$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4,65001);$il.Emit([Reflection.Emit.OpCodes]::Ret);$spoof.DefineMethodOverride($getter,[Text.Encoding].GetProperty('CodePage').GetMethod);[type[]]$ctorArgs=@([int],[Text.EncoderFallback],[Text.DecoderFallback]);$c3=$spoof.DefineConstructor([Reflection.MethodAttributes]::Public,[Reflection.CallingConventions]::Standard,$ctorArgs);$il=$c3.GetILGenerator();foreach($i in 0..3){$il.Emit([Reflection.Emit.OpCodes]::Ldarg,[int16]$i)};$il.Emit([Reflection.Emit.OpCodes]::Call,$type.GetConstructor($ctorArgs));$il.Emit([Reflection.Emit.OpCodes]::Ret);$spoofType=$spoof.CreateType()


$normal=$module.DefineType('NormalizedEncoding',[Reflection.TypeAttributes]::Public,$type);$seen=$normal.DefineField('Seen',[int],[Reflection.FieldAttributes]::Public);$mode=$normal.DefineField('Mode',[int],[Reflection.FieldAttributes]::Public);$c=$normal.DefineConstructor([Reflection.MethodAttributes]::Public,[Reflection.CallingConventions]::Standard,[type[]]@());$il=$c.GetILGenerator();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Call,$type.GetConstructor([type[]]@()));$il.Emit([Reflection.Emit.OpCodes]::Ret)
$m=$normal.DefineMethod('IsAlwaysNormalized',[Reflection.MethodAttributes]'Public,Virtual',[bool],[type[]]@([Text.NormalizationForm]));$il=$m.GetILGenerator();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_1);$il.Emit([Reflection.Emit.OpCodes]::Stfld,$seen);$ok=$il.DefineLabel();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$mode);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_M1);$il.Emit([Reflection.Emit.OpCodes]::Bne_Un,$ok);$il.Emit([Reflection.Emit.OpCodes]::Ldstr,'normalization callback');$il.Emit([Reflection.Emit.OpCodes]::Newobj,[InvalidOperationException].GetConstructor([type[]]@([string])));$il.Emit([Reflection.Emit.OpCodes]::Throw);$il.MarkLabel($ok);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$mode);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_1);$il.Emit([Reflection.Emit.OpCodes]::Ceq);$il.Emit([Reflection.Emit.OpCodes]::Ret);$normal.DefineMethodOverride($m,[Text.Encoding].GetMethod('IsAlwaysNormalized',[type[]]@([Text.NormalizationForm])));$normalType=$normal.CreateType()
$rows=[Collections.Generic.List[object]]::new()
foreach($kind in 0..4){foreach($cloned in @($false,$true)){foreach($form in @(-2147483648,-1,0,1,2,3,4,5,6,7,2147483647)){foreach($facade in @($false,$true)){
 $owner=switch($kind){0{$type.GetConstructor([type[]]@()).Invoke([object[]]@())}1{[Text.UTF8Encoding]::new($false,$false)}default{$normalType.GetConstructor([type[]]@()).Invoke([object[]]@())}};if($kind -ge 2){$normalType.GetField('Mode').SetValue($owner,[int]$(switch($kind){2{1}3{6}4{-1}}));$normalType.GetField('Seen').SetValue($owner,12345)};if($cloned){$owner=$owner.Clone()};$result=$null;$failure=$null
 try{$result=if($facade){$owner.IsAlwaysNormalized()}else{$owner.IsAlwaysNormalized(([Enum]::ToObject([Text.NormalizationForm],[int]$form)))}}catch{$e=$_.Exception;while($e.InnerException){$e=$e.InnerException};$failure=[ordered]@{type=$e.GetType().FullName;message=$e.Message;hResult=$e.HResult}}
 $rows.Add([ordered]@{kind=$kind;cloned=$cloned;form=$form;facade=$facade;result=$result;failure=$failure;seen=$(if($kind -ge 2){$normalType.GetField('Seen').GetValue($owner)}else{12345})})
}}}}
$values=@([Enum]::GetNames([Text.NormalizationForm])|ForEach-Object{[ordered]@{name=$_;value=[int][Enum]::Parse([Text.NormalizationForm],$_)}})
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();values=$values;rows=$rows.ToArray();qualification='SELECTED_NORMALIZATION_QUERY_DISPATCH_ONLY; NORMALIZATION_TRANSFORMS_FULL_ENUM_ABI_AND_TASK_ACCEPTANCE_OPEN'}
[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 12 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS normalization query capture: $($rows.Count) rows, $($values.Count) enum values"
